-- SEED: Enriquecimiento desde export de HubSpot (contactos/prospectos).
-- 1) Rellena email/teléfono/contacto VACÍOS de clientes y leads que ya existen
--    (match por nombre normalizado o por dominio de email corporativo) y agrega un
--    resumen de HubSpot a la nota. 2) Inserta prospectos NUEVOS no repetidos con
--    email Y teléfono. No pisa datos ya cargados. Idempotente. Correr una vez.

create or replace function _alnum(txt text) returns text language sql immutable as $$
  select regexp_replace(translate(lower(coalesce(txt,'')),'áéíóúüñ','aeiouun'),'[^a-z0-9]','','g') $$;

create temp table _hub (nombre text, clave text, dom text, contacto text, email text, telefono text, resumen text) on commit drop;

-- 1) Enriquecer CLIENTES existentes (rellena vacíos + resumen en la nota).
update clientes c set
  email    = coalesce(c.email, h.email),
  telefono = coalesce(c.telefono, h.telefono),
  contacto = coalesce(c.contacto, h.contacto),
  nota = case when position('HubSpot:' in coalesce(c.nota,'')) > 0 then c.nota
              when coalesce(c.nota,'') = '' then h.resumen
              else c.nota || E'\n' || h.resumen end
from _hub h
where _alnum(c.nombre) = h.clave
   or (h.dom <> '' and c.email is not null and split_part(lower(c.email),'@',2) = h.dom);

-- 2) Enriquecer LEADS existentes (copia inline: rellena email/teléfono/contacto vacíos).
update leads l set
  email    = coalesce(l.email, h.email),
  telefono = coalesce(l.telefono, h.telefono),
  contacto = coalesce(l.contacto, h.contacto),
  updated_at = now()
from _hub h
where regexp_replace(l.clave, '[^a-z0-9]', '', 'g') = h.clave
  and (l.email is null or l.telefono is null or l.contacto is null);

-- 3) Insertar prospectos NUEVOS (no repetidos) con email Y teléfono.
select h.nombre, 'prospeccion', 'mediano', 0, null, h.contacto, h.email, h.telefono, h.resumen
from _hub h
where h.email is not null and h.telefono is not null
  and not exists (select 1 from clientes c where _alnum(c.nombre) = h.clave)
  and not exists (select 1 from clientes c where h.dom <> '' and c.email is not null and split_part(lower(c.email),'@',2) = h.dom);

-- Resumen de lo cargado (opcional): cuántos prospectos HubSpot nuevos quedaron.
select count(*) as prospectos_hubspot from clientes where nota like 'HubSpot:%' and segmento='prospeccion';

drop function if exists _alnum(text);

